impl crate::m_01_stress::Entity3 {
    pub async fn create_many<'e, E>(
        executor: E,
        inputs: &[crate::m_01_stress::Entity3UncheckedCreateInput],
    ) -> sqlx::Result<u64>
    where
        E: sqlx::Executor<'e, Database = sqlx::Postgres>,
    {
        if inputs.is_empty() {
            return Ok(0);
        }
        let mut qb = sqlx::QueryBuilder::new(
            r#"INSERT INTO "table_entity3" ("rel_fk_id_1", "rel_fk_id_2", "field_1", "field_6", "field_7", "field_8", "rel_fk_id_3", "field_9", "field_10") "#,
        );
        qb.push_values(inputs, |mut row, input| {
            row.push_bind(input.rel_fk_id_1.clone());
            row.push_bind(input.rel_fk_id_2.clone());
            row.push_bind(input.field_1);
            row.push_bind(input.field_6);
            row.push_bind(input.field_7.clone());
            row.push_bind(input.field_8);
            row.push_bind(input.rel_fk_id_3.clone());
            row.push_bind(input.field_9);
            row.push_bind(input.field_10);
        });
        let result = qb.build().execute(executor).await?;
        Ok(result.rows_affected())
    }
}

